require 'header.php';
if(!admin()){http_response_code(403);die('La sincronización masiva desde Excel está disponible solo para administradores.');}
$p=db();$error='';$preview=null;$result=null;

function xlsx_col_index($ref){if(!preg_match('/^([A-Z]+)/i',$ref,$m))return 0;$s=strtoupper($m[1]);$n=0;for($i=0;$i<strlen($s);$i++)$n=$n*26+(ord($s[$i])-64);return $n-1;}
function xlsx_date_value($v){if($v===null||$v==='')return null;if(is_numeric($v)){return gmdate('Y-m-d',(int)round(((float)$v-25569)*86400));}$v=trim((string)$v);foreach(['Y-m-d','d-m-Y','d/m/Y','m/d/Y'] as $fmt){$d=DateTime::createFromFormat('!'.$fmt,$v);if($d&&$d->format($fmt)===$v)return $d->format('Y-m-d');}$ts=strtotime($v);return $ts?date('Y-m-d',$ts):null;}
function xlsx_read_plan($path){
 if(!class_exists('ZipArchive'))throw new RuntimeException('El servidor no tiene habilitado ZipArchive para leer archivos XLSX.');
 $zip=new ZipArchive();if($zip->open($path)!==true)throw new RuntimeException('No fue posible abrir el archivo XLSX.');
 $shared=[];$ss=$zip->getFromName('xl/sharedStrings.xml');
 if($ss!==false){$xml=simplexml_load_string($ss);if($xml)foreach($xml->si as $si){if(isset($si->t))$shared[]=(string)$si->t;else{$txt='';foreach($si->r as $r)$txt.=(string)$r->t;$shared[]=$txt;}}}
 $wb=simplexml_load_string($zip->getFromName('xl/workbook.xml'));$rels=simplexml_load_string($zip->getFromName('xl/_rels/workbook.xml.rels'));
 if(!$wb||!$rels){$zip->close();throw new RuntimeException('El libro Excel no tiene una estructura válida.');}
 $relMap=[];foreach($rels->Relationship as $rel)$relMap[(string)$rel['Id']]=(string)$rel['Target'];
 $sheetPath=null;$wb->registerXPathNamespace('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships');
 foreach($wb->sheets->sheet as $sheet){if(trim((string)$sheet['name'])==='Plan de Tareas'){$attrs=$sheet->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships');$rid=(string)$attrs['id'];$target=$relMap[$rid]??'';if($target)$sheetPath='xl/'.ltrim(str_replace('../','',$target),'/');break;}}
 if(!$sheetPath){$zip->close();throw new RuntimeException('No se encontró la hoja "Plan de Tareas". Use la plantilla oficial del sistema.');}
 $raw=$zip->getFromName($sheetPath);if($raw===false){$zip->close();throw new RuntimeException('No fue posible leer la hoja "Plan de Tareas".');}
 $sx=simplexml_load_string($raw);$rows=[];
 foreach($sx->sheetData->row as $row){$rnum=(int)$row['r'];if($rnum===1)continue;$vals=array_fill(0,25,'');foreach($row->c as $c){$idx=xlsx_col_index((string)$c['r']);if($idx<0||$idx>24)continue;$type=(string)$c['t'];$v='';if($type==='inlineStr'){$v=(string)$c->is->t;}elseif(isset($c->v)){$rawv=(string)$c->v;$v=$type==='s'?($shared[(int)$rawv]??''):$rawv;}$vals[$idx]=$v;}if(trim((string)$vals[0])!=='')$rows[]=$vals;}
 $zip->close();return $rows;
}
function norm_level($v){return strtoupper(trim($v))==='ETAPA'?'ETAPA':'PROCESO';}
function clean_amount($v){$v=trim((string)$v);if($v==='')return null;$v=str_replace(['$',' '],'',$v);if(substr_count($v,',')===1&&substr_count($v,'.')===0)$v=str_replace(',','.',$v);else$v=str_replace(',','',$v);return is_numeric($v)?(float)$v:null;}
function excel_row_to_task($r){return ['code'=>trim($r[0]),'level'=>norm_level($r[1]),'parent_code'=>trim($r[2])?:null,'area'=>trim($r[3]),'project'=>trim($r[4]),'task'=>trim($r[5]),'responsible'=>trim($r[6]),'priority'=>trim($r[7]),'status'=>trim($r[8]),'start_date'=>xlsx_date_value($r[9]),'end_date'=>xlsx_date_value($r[10]),'dependency'=>trim($r[17]),'purchase_milestone'=>trim($r[18]),'reference_no'=>trim($r[19]),'amount'=>clean_amount($r[20]),'provider'=>trim($r[21]),'next_milestone'=>trim($r[22]),'next_date'=>xlsx_date_value($r[23]),'risk'=>trim($r[24])];}
function changed_fields($old,$new){$labels=['level'=>'Nivel','parent_code'=>'Proceso padre','area'=>'Área / Unidad','project'=>'Proceso / Proyecto','task'=>'Etapa / Tarea','responsible'=>'Responsable','priority'=>'Prioridad','status'=>'Estado','start_date'=>'Fecha inicio','end_date'=>'Fecha término','dependency'=>'Dependencia / Observación','purchase_milestone'=>'Hito Compra Pública','reference_no'=>'N° Req./Licitación/OC','amount'=>'Monto','provider'=>'Proveedor','next_milestone'=>'Próximo hito','next_date'=>'Fecha próximo hito','risk'=>'Riesgo'];$out=[];foreach($labels as $k=>$label){$a=$old[$k]??null;$b=$new[$k]??null;if((string)$a!==(string)$b)$out[]=$label;}return $out;}
function save_upload_temp(){if(empty($_FILES['excel'])||$_FILES['excel']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Seleccione un archivo Excel .xlsx.');$name=$_FILES['excel']['name']??'';if(strtolower(pathinfo($name,PATHINFO_EXTENSION))!=='xlsx')throw new RuntimeException('Solo se admiten archivos .xlsx.');if(($_FILES['excel']['size']??0)>8*1024*1024)throw new RuntimeException('El archivo supera el máximo permitido de 8 MB.');$dir=__DIR__.'/tmp_imports';if(!is_dir($dir))@mkdir($dir,0755,true);$dest=$dir.'/'.bin2hex(random_bytes(16)).'.xlsx';if(!move_uploaded_file($_FILES['excel']['tmp_name'],$dest))throw new RuntimeException('No fue posible guardar temporalmente el archivo.');$_SESSION['excel_import_file']=$dest;return $dest;}
function remove_import_file(){$f=$_SESSION['excel_import_file']??'';if($f&&is_file($f))@unlink($f);unset($_SESSION['excel_import_file']);}

if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'preview';try{
 if($act==='preview'){
  remove_import_file();$file=save_upload_temp();$rows=xlsx_read_plan($file);$items=[];$newCount=0;$updateCount=0;$sameCount=0;$errors=0;$seen=[];
  foreach($rows as $i=>$r){$t=excel_row_to_task($r);$rowNo=$i+2;if(isset($seen[$t['code']])){$items[]=['row'=>$rowNo,'code'=>$t['code'],'task'=>$t['task'],'kind'=>'error','detail'=>'ID duplicado dentro del Excel'];$errors++;continue;}$seen[$t['code']]=1;if($t['task']===''){$items[]=['row'=>$rowNo,'code'=>$t['code'],'task'=>'','kind'=>'error','detail'=>'Falta Etapa / Tarea'];$errors++;continue;}$st=$p->prepare('SELECT * FROM tasks WHERE code=?');$st->execute([$t['code']]);$old=$st->fetch();if(!$old){$kind='new';$detail='Se incorporará como nuevo registro';$newCount++;}else{$chg=changed_fields($old,$t);if($chg){$kind='update';$detail='Cambios: '.implode(', ',$chg);$updateCount++;}else{$kind='same';$detail='Sin cambios';$sameCount++;}}$items[]=['row'=>$rowNo,'code'=>$t['code'],'task'=>$t['task'],'kind'=>$kind,'detail'=>$detail];}
  $preview=['items'=>$items,'new'=>$newCount,'update'=>$updateCount,'same'=>$sameCount,'errors'=>$errors,'count'=>count($rows)];
 }elseif($act==='confirm'){
  $file=$_SESSION['excel_import_file']??'';if(!$file||!is_file($file))throw new RuntimeException('La vista previa expiró. Vuelva a seleccionar el Excel.');
  $rows=xlsx_read_plan($file);$created=0;$updated=0;$unchanged=0;$failed=[];$seen=[];$fields=['level','parent_code','area','project','task','responsible','priority','status','start_date','end_date','dependency','purchase_milestone','reference_no','amount','provider','next_milestone','next_date','risk'];$p->beginTransaction();
  foreach($rows as $i=>$r){$t=excel_row_to_task($r);$rowNo=$i+2;if(isset($seen[$t['code']])){$failed[]='Fila '.$rowNo.': ID duplicado '.$t['code'];continue;}$seen[$t['code']]=1;if($t['code']===''||$t['task']===''){$failed[]='Fila '.$rowNo.': faltan datos obligatorios';continue;}$st=$p->prepare('SELECT * FROM tasks WHERE code=?');$st->execute([$t['code']]);$old=$st->fetch();
   if(!$old){$cols=array_merge(['code'],$fields,['created_by','updated_by','original_start_date','original_end_date']);$marks=implode(',',array_fill(0,count($cols),'?'));$vals=[$t['code']];foreach($fields as $f)$vals[]=$t[$f];$vals[]=current_user_id();$vals[]=current_user_id();$vals[]=$t['start_date'];$vals[]=$t['end_date'];$p->prepare('INSERT INTO tasks('.implode(',',$cols).') VALUES('.$marks.')')->execute($vals);audit('IMPORTAR_EXCEL_NUEVO',$t['code'].' · '.$t['task'].' · origen: Excel offline');$created++;}
   else{$chg=changed_fields($old,$t);if(!$chg){$unchanged++;continue;}$oldStart=$old['start_date']?:null;$oldEnd=$old['end_date']?:null;if($oldStart!==$t['start_date']||$oldEnd!==$t['end_date']){$p->prepare('INSERT INTO task_date_history(task_id,old_start_date,new_start_date,old_end_date,new_end_date,reason,changed_by) VALUES(?,?,?,?,?,?,?)')->execute([$old['id'],$oldStart,$t['start_date'],$oldEnd,$t['end_date'],'Sincronización desde planilla Excel trabajada sin conexión',current_user_id()]);}$set=implode(',',array_map(fn($f)=>$f.'=?',$fields)).',updated_by=?,updated_at=CURRENT_TIMESTAMP';$vals=[];foreach($fields as $f)$vals[]=$t[$f];$vals[]=current_user_id();$vals[]=$old['id'];$p->prepare('UPDATE tasks SET '.$set.' WHERE id=?')->execute($vals);audit('IMPORTAR_EXCEL_ACTUALIZAR',$t['code'].' · campos modificados: '.implode(', ',$chg).' · origen: Excel offline');$updated++;}
  }
  $p->commit();remove_import_file();audit('IMPORTAR_EXCEL','Sincronización finalizada · nuevos '.$created.' · actualizados '.$updated.' · sin cambios '.$unchanged.' · observaciones '.count($failed));$result=['created'=>$created,'updated'=>$updated,'same'=>$unchanged,'failed'=>$failed];
 }elseif($act==='cancel'){remove_import_file();}
}catch(Throwable $e){if($p->inTransaction())$p->rollBack();$error=$e->getMessage();}}
